package com.alpharip.staffmod.BuildTimelapse.camera;
import java.util.*;public final class CameraPathInterpolator {public CameraPose sample(CameraPath p,double progress){List<CameraWaypoint>w=p.getWaypoints();if(w.isEmpty())return CameraPose.origin();if(w.size()==1)return w.get(0).getPose();double v=Math.max(0,Math.min(1,progress))*(w.size()-1);int i=Math.min(w.size()-2,(int)v);double t=v-i;t=t*t*(3-2*t);CameraPose a=w.get(i).getPose(),b=w.get(i+1).getPose();return new CameraPose(l(a.x,b.x,t),l(a.y,b.y,t),l(a.z,b.z,t),angle(a.yaw,b.yaw,t),(float)l(a.pitch,b.pitch,t),(float)l(a.roll,b.roll,t),(float)l(a.fov,b.fov,t));}private double l(double a,double b,double t){return a+(b-a)*t;}private float angle(float a,float b,double t){return(float)(a+(((b-a+540)%360)-180)*t);}}
